#define CGLTF_IMPLEMENTATION
#include "cgltf.h"
#undef CGLTF_IMPLEMENTATION
#include "engine/world_road_traffic.cpp"
#include <cstdlib>
static void require(bool b,const char*s){if(!b){fprintf(stderr,"FAIL %s\n",s);exit(1);}}
int main(int argc,char**argv){require(argc==4,"args models manifest report");Manifest m;std::string why;require(manifest_load(argv[2],m,why),"actual manifest parse");std::filesystem::path root=std::filesystem::path(argv[2]).parent_path();const char*stems[]={"purchased_character_traveler","village_character_travelerwoman","purchased_character_craftsman","purchased_character_wayfarer"};std::array<std::vector<std::array<double,3>>,6> points;unsigned long long checks=0,camera_checks=0;double max_horizontal=0,max_top=0;
 for(unsigned bank=0;bank<6;bank++){unsigned walk=bank==4?16:8;for(unsigned i=0;i<walk+4;i++){std::filesystem::path p;if(bank<4){char name[128];snprintf(name,sizeof(name),"%s_%s_%02u.glb",stems[bank],i<walk?"walk":"idle",i<walk?i:i-walk);p=std::filesystem::path(argv[1])/name;}else p=root/(bank==4?m.mounted[i]:m.puller[i]);require(shape_points(p,points[bank]),"actual source point capture");}}
 require(shape_points(root/m.body,points[5],m.offset),"cart source points");std::vector<std::array<double,3>>wheel;require(shape_points(root/m.wheel,wheel),"wheel source points");for(unsigned j=0;j<2;j++){auto off=m.axle[j];for(unsigned k=0;k<3;k++)off[k]+=m.offset[k];require(shape_points(root/m.wheel,points[5],off),"wheel same production capture");}
 std::array<Profile,6> profiles;for(unsigned bank=0;bank<6;bank++){auto&f=profiles[bank];fit_profile(f,points[bank]);for(auto&p:points[bank])for(unsigned a=0;a<=64;a++){double t=-.16+.32*a/64,c=cos(t),s=sin(t),z=s*p[1]+c*p[2],y=c*p[1]-s*p[2],r=f.radius,near=std::clamp(z,-std::max(0.,f.rear-r),std::max(0.,f.front-r)),excess=std::hypot(p[0],z-near)-r;max_horizontal=std::max(max_horizontal,excess);max_top=std::max(max_top,y-f.height);require(excess<=1e-8&&y<=f.height+1e-8,"actual source within pitched capsule/top");if(checks%97==0&&y>=0){const auto body=world_road_traffic_core::capsule({0,0,0,0,1},f);require(!world_road_traffic_core::camera_capsule_clear(body,p[0],y,z,p[0],y,z,.01,.02),"actual source point enclosed by camera body query");++camera_checks;}checks++;}}
 auto&f=profiles[5];for(unsigned j=0;j<2;j++)for(auto&p:wheel)for(unsigned spin=0;spin<64;spin++)for(double t:{-.16,0.,.16}){double theta=spin*2*world_road_traffic_core::pi/64,yy=cos(theta)*p[1]-sin(theta)*p[2]+m.axle[j][1]+m.offset[1],zz=sin(theta)*p[1]+cos(theta)*p[2]+m.axle[j][2]+m.offset[2],xx=p[0]+m.axle[j][0]+m.offset[0],z=sin(t)*yy+cos(t)*zz,y=cos(t)*yy-sin(t)*zz,near=std::clamp(z,-(f.rear-f.radius),f.front-f.radius),excess=std::hypot(xx,z-near)-f.radius;max_horizontal=std::max(max_horizontal,excess);max_top=std::max(max_top,y-f.height);require(excess<=1e-8&&y<=f.height+1e-8,"rolling pitched wheel enclosed");checks++;}
 FILE*out=fopen(argv[3],"wb");require(out,"reportwrite");fprintf(out,"{\"passed\":true,\"checks\":%llu,\"maximum_horizontal_excess_m\":%.12g,\"maximum_top_excess_m\":%.12g,\"pitch_range\":[-0.16,0.16],\"wheel_spin_samples\":64,\"profiles\":[",checks,max_horizontal,max_top);for(unsigned bank=0;bank<6;bank++){auto&f=profiles[bank];fprintf(out,"%s{\"bank\":%u,\"points\":%zu,\"radius\":%.12g,\"front\":%.12g,\"rear\":%.12g,\"height\":%.12g}",bank?",":"",bank,points[bank].size(),f.radius,f.front,f.rear,f.height);}fprintf(out,"]}\n");fclose(out);printf("PASS %llu actual profile points; %llu actual source camera-enclosure samples\n",checks,camera_checks);}
